<?php require 'admin_bootstrap.php'; $title='Administration Inbox'; $feedback=$pdo->query('SELECT * FROM feedback ORDER BY created_at DESC')->fetchAll(); require 'header.php'; admin_flash_html(); ?>
<section class="section"><div class="section-intro"><div><span class="eyebrow">ADMINISTRATION INBOX</span><h2>Feedback &amp; Problem Reports</h2><p class="muted">Student messages submitted through Contact Administration.</p></div></div>
<?php if(!$feedback): ?><p class="muted">No messages yet.</p><?php endif; ?><?php foreach($feedback as $r): ?><div class="feedback-item"><div class="card-head"><div><b><?=e($r['subject'])?></b><div class="muted"><?=e($r['name'])?> · <?=e($r['email'])?><?php if($r['student_id']): ?> · <?=e($r['student_id'])?><?php endif;?></div></div><span class="badge <?=str_replace(' ','-',strtolower($r['status']))?>"><?=e($r['status'])?></span></div><div class="feedback-type"><?=e($r['type'])?> · <?=date('M d, Y g:i A',strtotime($r['created_at']))?></div><p><?=nl2br(e($r['message']))?></p><form method="post" class="inline-form"><?=admin_form_return('admin_inbox.php')?><input type="hidden" name="action" value="feedback_status"><input type="hidden" name="feedback_id" value="<?=$r['id']?>"><select name="feedback_action"><option <?=$r['status']==='New'?'selected':''?>>New</option><option <?=$r['status']==='In Review'?'selected':''?>>In Review</option><option <?=$r['status']==='Resolved'?'selected':''?>>Resolved</option></select><button class="btn">Update</button></form></div><?php endforeach; ?></section>
